import{_ as t,o,c as d,ai as a}from"./chunks/framework.jD4ETUAz.js";const u=JSON.parse('{"title":"Tools and configuration reference","description":"Reference for the eight cninfo-mcp tools: security search, report listings, announcement search, document reading, financial data and downloads.","frontmatter":{"title":"Tools and configuration reference","description":"Reference for the eight cninfo-mcp tools: security search, report listings, announcement search, document reading, financial data and downloads.","checkedAgainst":"3.0.0","editLink":false,"translation":"reference/tools.md","head":[["link",{"rel":"canonical","href":"https://youhaozhao.github.io/cninfo-mcp/en/reference/tools"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:site_name","content":"cninfo-mcp"}],["meta",{"property":"og:title","content":"Tools and configuration reference | cninfo-mcp"}],["meta",{"property":"og:description","content":"Reference for the eight cninfo-mcp tools: security search, report listings, announcement search, document reading, financial data and downloads."}],["meta",{"property":"og:url","content":"https://youhaozhao.github.io/cninfo-mcp/en/reference/tools"}],["meta",{"property":"og:image","content":"https://youhaozhao.github.io/cninfo-mcp/og-en.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Tools and configuration reference | cninfo-mcp"}],["meta",{"name":"twitter:description","content":"Reference for the eight cninfo-mcp tools: security search, report listings, announcement search, document reading, financial data and downloads."}],["meta",{"name":"twitter:image","content":"https://youhaozhao.github.io/cninfo-mcp/og-en.png"}],["link",{"rel":"alternate","hreflang":"zh","href":"https://youhaozhao.github.io/cninfo-mcp/reference/tools"}],["link",{"rel":"alternate","hreflang":"en","href":"https://youhaozhao.github.io/cninfo-mcp/en/reference/tools"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://youhaozhao.github.io/cninfo-mcp/en/reference/tools"}],["meta",{"property":"og:locale:alternate","content":"zh_CN"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@graph\\":[{\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Home\\",\\"item\\":\\"https://youhaozhao.github.io/cninfo-mcp/en/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":2,\\"name\\":\\"Tools and configuration reference\\",\\"item\\":\\"https://youhaozhao.github.io/cninfo-mcp/en/reference/tools\\"}]}]}"]]},"headers":[],"relativePath":"en/reference/tools.md","filePath":"en/reference/tools.md","lastUpdated":1794815217000}'),n={name:"en/reference/tools.md"};function r(i,e,c,s,l,h){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="tools-and-configuration-reference" tabindex="-1">Tools and configuration reference <a class="header-anchor" href="#tools-and-configuration-reference" aria-label="Permalink to &quot;Tools and configuration reference&quot;">​</a></h1><p>This page is an English rendering of the <a href="/cninfo-mcp/reference/tools">Chinese reference</a>, which is generated from the repository and is always current. It was last checked against version 3.0.0.</p><p>Every <code>stock</code> argument accepts a code or a Chinese short name: <code>600519</code>, <code>000001.SZ</code>, <code>sh600519</code>, <code>920185</code> (Beijing Stock Exchange, old and new codes both work), <code>00700.HK</code>, <code>贵州茅台</code>.</p><h2 id="find-and-search" tabindex="-1">Find and search <a class="header-anchor" href="#find-and-search" aria-label="Permalink to &quot;Find and search&quot;">​</a></h2><h3 id="search-securities" tabindex="-1"><code>search_securities</code> <a class="header-anchor" href="#search-securities" aria-label="Permalink to &quot;`search_securities`&quot;">​</a></h3><p>Find securities by code, short name or pinyin initials. Covers A and B shares in Shanghai, Shenzhen and Beijing, and Hong Kong stocks; funds and bonds are found by exact code.</p><ul><li><code>query</code> (required): a code, part of a name, or pinyin initials, such as <code>茅台</code>, <code>gzmt</code>, <code>6005</code></li><li><code>limit</code> (optional): number of results, default 10</li></ul><h3 id="list-reports" tabindex="-1"><code>list_reports</code> <a class="header-anchor" href="#list-reports" aria-label="Permalink to &quot;`list_reports`&quot;">​</a></h3><p>List a company&#39;s periodic reports or prospectuses.</p><ul><li><code>stock</code> (required)</li><li><code>report_type</code> (optional): report type, default <code>annual</code></li><li><code>year</code> (optional): fiscal year of the report; for prospectuses, the disclosure year. Omit it for all years</li><li><code>include_variants</code> (optional): also return summaries, English versions and other variants, default <code>false</code></li></ul><p>Values of <code>report_type</code>:</p><table tabindex="0"><thead><tr><th>Value</th><th>Report</th></tr></thead><tbody><tr><td><code>annual</code></td><td>Annual report</td></tr><tr><td><code>semiannual</code></td><td>Semi-annual (interim) report</td></tr><tr><td><code>q1</code></td><td>First-quarter report</td></tr><tr><td><code>q3</code></td><td>Third-quarter report</td></tr><tr><td><code>prospectus</code></td><td>IPO prospectus, including the preliminary prospectus</td></tr></tbody></table><p>Each result has a <code>kind</code>:</p><table tabindex="0"><thead><tr><th><code>kind</code></th><th>Meaning</th><th>Returned by default</th></tr></thead><tbody><tr><td><code>main</code></td><td>Full report</td><td>Yes</td></tr><tr><td><code>revised</code></td><td>Updated or revised full report</td><td>Yes</td></tr><tr><td><code>summary</code></td><td>Summary (including the short-form quarterly text used in Shenzhen)</td><td>No</td></tr><tr><td><code>english</code></td><td>English version</td><td>No</td></tr><tr><td><code>h_share</code></td><td>Edition prepared under Hong Kong rules by a dual-listed company</td><td>No</td></tr><tr><td><code>other</code></td><td>Cancelled and other cases</td><td>No</td></tr></tbody></table><p>Announcements about a report, such as a correction notice, are not reports and do not appear in the results.</p><h3 id="search-announcements" tabindex="-1"><code>search_announcements</code> <a class="header-anchor" href="#search-announcements" aria-label="Permalink to &quot;`search_announcements`&quot;">​</a></h3><p>Search announcements, newest first by default.</p><ul><li><code>stock</code> (optional): code or short name; several may be comma-separated (up to 10). Omit it to search the whole market</li><li><code>keyword</code> (optional): words that must appear in the title, such as <code>回购</code> (share repurchase)</li><li><code>categories</code> (optional): announcement categories, see the table below</li><li><code>start_date</code> / <code>end_date</code> (optional): <code>YYYY-MM-DD</code>, Beijing time, inclusive</li><li><code>market</code> (optional): board filter for market-wide searches. <code>sh</code> Shanghai, <code>shmb</code> Shanghai main board, <code>shkcp</code> STAR Market, <code>sz</code> Shenzhen, <code>szmb</code> Shenzhen main board, <code>szcy</code> ChiNext, <code>bj</code> Beijing Stock Exchange</li><li><code>source</code> (optional): <code>announcements</code> (default) or <code>investor_relations</code> (records of investor meetings and site visits)</li><li><code>sort</code> (optional): <code>newest</code> (default) or <code>oldest</code></li><li><code>limit</code> (optional): default 30, maximum 200</li><li><code>offset</code> (optional): position to continue from</li></ul><p>The result includes <code>total</code> (the number of matches). When there are more results it also includes <code>next_offset</code>, which is passed as <code>offset</code> in the next call.</p><p>Announcement categories:</p><table tabindex="0"><thead><tr><th>Name</th><th>Category</th><th>Name</th><th>Category</th></tr></thead><tbody><tr><td><code>annual_report</code></td><td>Annual reports</td><td><code>equity_incentive</code></td><td>Equity incentives</td></tr><tr><td><code>semiannual_report</code></td><td>Semi-annual reports</td><td><code>rights_issue</code></td><td>Rights issues</td></tr><tr><td><code>q1_report</code></td><td>Q1 reports</td><td><code>unlock</code></td><td>Lock-up expiries</td></tr><tr><td><code>q3_report</code></td><td>Q3 reports</td><td><code>corporate_bond</code></td><td>Corporate bonds</td></tr><tr><td><code>earnings_forecast</code></td><td>Earnings forecasts</td><td><code>convertible_bond</code></td><td>Convertible bonds</td></tr><tr><td><code>dividend</code></td><td>Dividends and distributions</td><td><code>other_financing</code></td><td>Other financing</td></tr><tr><td><code>board</code></td><td>Board of directors</td><td><code>equity_change</code></td><td>Changes in shareholding</td></tr><tr><td><code>supervisory_board</code></td><td>Supervisory board</td><td><code>correction</code></td><td>Supplements and corrections</td></tr><tr><td><code>shareholder_meeting</code></td><td>Shareholder meetings</td><td><code>clarification</code></td><td>Clarifications and apologies</td></tr><tr><td><code>operations</code></td><td>Day-to-day operations</td><td><code>risk_warning</code></td><td>Risk warnings</td></tr><tr><td><code>governance</code></td><td>Corporate governance</td><td><code>st_delisting</code></td><td>Special treatment and delisting</td></tr><tr><td><code>intermediary</code></td><td>Intermediary reports</td><td><code>delisting_period</code></td><td>Delisting consolidation period</td></tr><tr><td><code>ipo</code></td><td>Initial public offerings</td><td><code>placement</code></td><td>Follow-on offerings</td></tr></tbody></table><p>Categories with <code>source=investor_relations</code>: <code>research</code> (site visits and research meetings), <code>roadshow</code>, <code>media_interview</code>, <code>ir_policy</code> (investor-relations policies).</p><p>Categories apply to Shanghai, Shenzhen and Beijing listings only. For Hong Kong announcements, search by <code>keyword</code>.</p><h2 id="read" tabindex="-1">Read <a class="header-anchor" href="#read" aria-label="Permalink to &quot;Read&quot;">​</a></h2><h3 id="read-document" tabindex="-1"><code>read_document</code> <a class="header-anchor" href="#read-document" aria-label="Permalink to &quot;`read_document`&quot;">​</a></h3><p>Read the text of an announcement or report (PDF, or HTML for older filings). The result is plain text.</p><ul><li><code>url</code> (required): a document URL returned by <code>list_reports</code> or <code>search_announcements</code></li><li><code>pages</code> (optional): page ranges, such as <code>5</code>, <code>10-20</code>, <code>1-3,8</code></li><li><code>query</code> (optional): words to locate inside the document, space-separated; any match counts</li><li><code>max_chars</code> (optional): output limit in characters, default 20000</li></ul><p>Three modes:</p><ol><li><code>url</code> only: page count, table of contents and the opening pages.</li><li>With <code>query</code>: the matching pages with snippets, to locate a section in a long report.</li><li>With <code>pages</code>: the full text of those pages. If it exceeds <code>max_chars</code>, the result ends with the <code>pages</code> value to continue from.</li></ol><h2 id="structured-data" tabindex="-1">Structured data <a class="header-anchor" href="#structured-data" aria-label="Permalink to &quot;Structured data&quot;">​</a></h2><p>Shanghai, Shenzhen and Beijing listings only.</p><h3 id="get-financials" tabindex="-1"><code>get_financials</code> <a class="header-anchor" href="#get-financials" aria-label="Permalink to &quot;`get_financials`&quot;">​</a></h3><ul><li><code>stock</code> (required)</li><li><code>statements</code> (optional): <code>indicators</code> (key ratios), <code>income</code>, <code>balance</code>, <code>cashflow</code>; several may be requested, default <code>indicators</code></li><li><code>period</code> (optional): <code>annual</code> (default), <code>semiannual</code>, <code>q1</code>, <code>q3</code>. Quarterly and semi-annual figures are cumulative year-to-date</li><li><code>periods</code> (optional): number of recent periods, default 5 (the upstream source provides at most 5)</li></ul><p>Statement amounts are in units of 10,000 CNY (万元) and are the condensed figures from CNINFO&#39;s company pages (main line items). For complete line items, read the report itself with <code>read_document</code>.</p><h3 id="get-company-data" tabindex="-1"><code>get_company_data</code> <a class="header-anchor" href="#get-company-data" aria-label="Permalink to &quot;`get_company_data`&quot;">​</a></h3><ul><li><code>stock</code> (required)</li><li><code>datasets</code> (required): one or more datasets (up to 8), fetched concurrently</li><li><code>limit</code> (optional): rows per dataset, default 20</li></ul><table tabindex="0"><thead><tr><th>Dataset</th><th>Content</th><th>Dataset</th><th>Content</th></tr></thead><tbody><tr><td><code>profile</code></td><td>Company profile</td><td><code>unlocks</code></td><td>Lock-up expiries</td></tr><tr><td><code>executives</code></td><td>Directors, supervisors and executives</td><td><code>pledges</code></td><td>Share pledges</td></tr><tr><td><code>dividends</code></td><td>Dividend history</td><td><code>margin_trading</code></td><td>Margin trading</td></tr><tr><td><code>share_structure</code></td><td>Share capital structure</td><td><code>block_trades</code></td><td>Block trades</td></tr><tr><td><code>shareholder_count</code></td><td>Number of shareholders</td><td><code>shareholder_trades</code></td><td>Shareholder purchases and sales</td></tr><tr><td><code>top_shareholders</code></td><td>Top ten shareholders</td><td><code>executive_trades</code></td><td>Changes in holdings of directors and executives</td></tr><tr><td><code>top_float_shareholders</code></td><td>Top ten holders of tradable shares</td><td><code>dragon_tiger</code></td><td>Exchange trading-disclosure list (龙虎榜)</td></tr><tr><td><code>fund_holdings</code></td><td>Fund holdings</td><td></td><td></td></tr></tbody></table><h2 id="download" tabindex="-1">Download <a class="header-anchor" href="#download" aria-label="Permalink to &quot;Download&quot;">​</a></h2><h3 id="download-reports" tabindex="-1"><code>download_reports</code> <a class="header-anchor" href="#download-reports" aria-label="Permalink to &quot;`download_reports`&quot;">​</a></h3><p>Save periodic reports or prospectuses as PDF files in the download directory. The selection is the same as <code>list_reports</code> (full reports only).</p><ul><li><code>stock</code> (required)</li><li><code>report_type</code> (optional): default <code>annual</code></li><li><code>year</code> (optional): omit to download every year</li><li><code>save_path</code> (optional): a sub-directory inside the download root, such as <code>annual/2024</code>. Paths outside the root are rejected</li></ul><h3 id="download-documents" tabindex="-1"><code>download_documents</code> <a class="header-anchor" href="#download-documents" aria-label="Permalink to &quot;`download_documents`&quot;">​</a></h3><ul><li><code>urls</code> (required): a list of document URLs (up to 50)</li><li><code>save_path</code> (optional): as above</li></ul><p>Files are named <code>code_name_title_announcementID.pdf</code>. A file that already exists is not downloaded again. Each file is handled independently, and failures are listed one by one in <code>failures</code>.</p><h2 id="prompt-templates" tabindex="-1">Prompt templates <a class="header-anchor" href="#prompt-templates" aria-label="Permalink to &quot;Prompt templates&quot;">​</a></h2><ul><li><code>company_research</code>: an in-depth research brief on a listed company</li><li><code>earnings_review</code>: a review of the latest periodic report</li></ul><h2 id="partial-results" tabindex="-1">Partial results <a class="header-anchor" href="#partial-results" aria-label="Permalink to &quot;Partial results&quot;">​</a></h2><p>Results that involve several upstream requests carry a <code>complete</code> field. If some pages, datasets or files fail, what was retrieved is still returned, <code>complete</code> is <code>false</code>, and <code>warnings</code> or <code>errors</code> describe what is missing.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration {#configuration}&quot;">​</a></h2><p>All settings are environment variables, and all are optional.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Purpose</th><th>Default</th></tr></thead><tbody><tr><td><code>CNINFO_MCP_DOWNLOAD_DIR</code></td><td>Download root. The download tools can only write inside it</td><td><code>~/Downloads/cninfo-mcp</code></td></tr><tr><td><code>CNINFO_MCP_CACHE_DIR</code></td><td>Cache for the securities list and for documents that were read, with their text</td><td><code>cninfo-mcp</code> in the platform cache directory</td></tr><tr><td><code>CNINFO_MCP_CACHE_MAX_MB</code></td><td>Document cache limit; least recently used files are evicted beyond it</td><td><code>1024</code></td></tr><tr><td><code>CNINFO_MCP_CONCURRENCY</code></td><td>Simultaneous requests to CNINFO (1 to 8)</td><td><code>4</code></td></tr><tr><td><code>CNINFO_MCP_TIMEOUT_MS</code></td><td>Timeout of a single request, in milliseconds</td><td><code>30000</code></td></tr><tr><td><code>CNINFO_MCP_DEBUG</code></td><td>Set to <code>1</code> to log upstream requests, retries and throttling to stderr</td><td>unset</td></tr></tbody></table><p>Command line:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @youhaozhao/cninfo-mcp</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # start the MCP server (stdio)</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @youhaozhao/cninfo-mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> probe</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # online self-test: announcement query, financial data, document reading</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @youhaozhao/cninfo-mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> selftest</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # offline self-test: is the installation itself (PDF text extraction) working</span></span></code></pre></div><h2 id="coverage-and-limits" tabindex="-1">Coverage and limits <a class="header-anchor" href="#coverage-and-limits" aria-label="Permalink to &quot;Coverage and limits&quot;">​</a></h2><ul><li>Announcement search: companies listed in Shanghai, Shenzhen and Beijing (including B shares) and Hong Kong announcements; announcements of funds and bonds can be searched by code.</li><li><code>list_reports</code>, <code>get_financials</code>, <code>get_company_data</code>: Shanghai, Shenzhen and Beijing listings.</li><li>Announcements are searched by title keyword. There is no full-text search across announcements; inside a single document, keywords can be located with <code>query</code>.</li><li>Scanned documents (some older filings) have no text layer and cannot be read as text.</li><li>No real-time quotes or price history.</li></ul>',55)])])}const m=t(n,[["render",r]]);export{u as __pageData,m as default};
